def add_recovery\(p, K, gate=0.5, mask_update=True, min_seg_ext=True, clamp_mode='sym'\):
    out = {}
    for vid, entry in p.items\(\):
        anoms = [dict\(a\) for a in entry['anomalies']]
        cat = gt[vid]['category']
        e = curves.get\(vid\)
        if e is None or cat not in \(e.get\('rel'\) or {}\):
