        rel = e['rel'][cat]; ts = e['ts']
        if rel is None or len\(rel\) < 3:
            out[vid] = {'anomalies': anoms}; continue
        mask = np.zeros\(len\(ts\), bool\)
        for a in anoms:
            mask |= \(ts >= a['t_start']\) & \(ts <= a['t_end']\)
        max_dur = CATEGORY_DURATION_PRIORS.get\(cat, {}\).get\('expected_duration', \(3.0,30.0\)\)[1]
        min_seg = CATEGORY_DURATION_PRIORS.get\(cat, {}\).get\('min_segment', 1.5\)
        rmax = float\(rel.max\(\)\); p20 = float\(np.percentile\(rel, 20\)\)
        for _ in range\(K\):
            avail = np.where\(~mask\)[0]
            if len\(avail\) == 0: break
            t2 = int\(avail[np.argmax\(rel[avail]\)]\)
            if rel[t2] < gate * rmax: break
            hm = \(float\(rel[t2]\) + p20\) / 2.0
            L = t2
            while L-1 >= 0 and rel[L-1] >= hm: L -= 1
            R = t2
            while R+1 < len\(ts\) and rel[R+1] >= hm: R += 1
            t_s, t_e = float\(ts[L]\), float\(ts[R]\)
            if t_e - t_s > max_dur:
                if clamp_mode == 'sym':
                    half = max_dur/2
                    t_s, t_e = max\(t_s, float\(ts[t2]\)-half\), min\(t_e, float\(ts[t2]\)+half\)
                elif clamp_mode == 'left':
                    t_s = max\(t_s, t_e - max_dur\)
                elif clamp_mode == 'none':
                    pass
            if t_e - t_s < min_seg and min_seg_ext:
                t_e = t_s + min_seg
            if t_e - t_s <= 0: break
            anoms.append\({'t_start': t_s, 't_end': t_e, 'confidence': 0.01, 'anomaly_type': cat}\)
            if mask_update:
                mask |= \(ts >= t_s\) & \(ts <= t_e\)
        out[vid] = {'anomalies': anoms}
    return out

