candpat = re.compile\(r'Candidate \\d+: \([\\d.]+\)s-\([\\d.]+\)s score=\([\\d.]+\)'\)
def active_videos\(idx\): return [v for v in starts if starts[v] <= idx <= dones.get\(v, 10**9\)]
def iou\(a,b\):
    ov = max\(0.0, min\(a[1],b[1]\)-max\(a[0],b[0]\)\); un = max\(a[1],b[1]\)-min\(a[0],b[0]\)
    return ov/un if un>0 else 0.0

# Step 1: per-video candidate pool from ALL candidate lines in the video's block,
# filtered by duration sanity; then keep only candidates consistent with finals OR
# with a CLIPBound line whose window matches \(chain evidence\).
boundpat = re.compile\(r'\\[\(CLIPBound|VLM-Bound\)\\] \([\\d.]+\)-\([\\d.]+\)s -> \([\\d.]+\)-\([\\d.]+\)s\(?: \\\(contrast=\([\\d.]+\), cat=\(\\S+\)\\\)\)?'\)
